// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }
    function testFuzz_property(address attacker, uint256 amount, bytes calldata data) public {
        vm.assume(attacker != c.owner());
        vm.assume(amount <= address(this).balance);
        vm.deal(address(c), amount);
        bool ok;
        vm.prank(attacker);
        try c.sendMoney(address(0), amount, data) { ok = true; } catch { ok = false; }
        assertTrue(!ok);
    }
}
